#!/bin/sh
# Real CLI checks for the installed unzoo.
#
# Run by test_package/conanfile.py as `sh test.sh <workdir>`.  The workdir
# already contains good.zoo, a spec-valid zoo archive with one stored member,
# generated by the conanfile.
#
# unzoo prints "extracted" only when the member's CRC-16 matches the value
# recorded in the directory entry, so check 2 doubles as the CRC check.
#
# POSIX sh only; the payload is compared line by line with shell builtins
# rather than with cmp/diff, so no particular utility set is required.
set -eu

workdir="${1:-.}"
cd "$workdir"

fail() {
    echo "FAIL: $1" >&2
    exit 1
}

MEMBER="HELLO.TXT"
EXPECTED_LINE="unzoo round-trip payload 0123456789"

# 1. listing must name the member, and must not report a bad directory entry
#    (that error appears when the posnxt==0 terminator entry is missing).
unzoo -l good.zoo > view.log 2>&1
grep -q "$MEMBER" view.log || fail "unzoo -l did not list '$MEMBER': $(cat view.log)"
if grep -q "bad directory entry" view.log; then
    fail "unzoo rejected the archive directory: $(cat view.log)"
fi
echo "ok   unzoo -l listed $MEMBER (directory walk terminated cleanly)"

# 2. extraction must succeed and the member CRC must verify.
unzoo -x good.zoo > extract.log 2>&1
grep -q "extracted" extract.log || fail "unzoo -x did not report extraction: $(cat extract.log)"
if grep -q "CRC failed" extract.log; then
    fail "unzoo reported a CRC failure: $(cat extract.log)"
fi
echo "ok   unzoo -x extracted and the member CRC verified"

# 3. the extracted bytes must match the payload exactly.
[ -f "$MEMBER" ] || fail "unzoo -x did not produce $MEMBER"
n=0
while IFS= read -r line; do
    n=$((n + 1))
    [ "$line" = "$EXPECTED_LINE" ] || fail "$MEMBER line $n is '$line', expected '$EXPECTED_LINE'"
done < "$MEMBER"
[ "$n" -eq 1 ] || fail "$MEMBER should hold exactly 1 line, got $n"
echo "ok   extracted payload round-tripped byte for byte"

echo "all unzoo CLI checks passed"
